// Isola le firme mai viste (stato persistito nel workflow) rispetto all'ultimo giro.
const result = $input.first().json.result || [];
const state = $getWorkflowStaticData('global');
const viste = new Set(state.viste || []);
const nuove = result.filter(r => !viste.has(r.signature) && !r.err);
for (const r of result) viste.add(r.signature);
state.viste = [...viste].slice(-500);
const primoGiro = !state.avviato;
state.avviato = true;
// al primo giro salva solo la base, non avvisa (altrimenti spammerebbe tutto lo storico)
return primoGiro ? [] : nuove.map(r => ({ json: { signature: r.signature, slot: r.slot } }));
